add_filter( 'woocommerce_my_account_my_orders_actions', 'perfectpixel_refund_request_action', 30, 2 );
add_action( 'woocommerce_view_order', 'perfectpixel_refund_request_form', 30 );
add_action( 'template_redirect', 'perfectpixel_refund_request_submit' );

function perfectpixel_refund_request_allowed( $order ) {
	if ( ! $order || ! $order->has_status( 'completed' ) || $order->get_meta( '_perfectpixel_refund_requested' ) || ! $order->get_date_completed() ) {
		return false;
	}
	return ( time() - $order->get_date_completed()->getTimestamp() ) <= max( 1, (int) '{{refund_request_days}}' ) * DAY_IN_SECONDS;
}

function perfectpixel_refund_request_action( $actions, $order ) {
	if ( perfectpixel_refund_request_allowed( $order ) ) {
		$actions['perfectpixel-refund'] = array(
			'url'  => $order->get_view_order_url() . '#perfectpixel-refund',
			'name' => '{{refund_request_button}}',
		);
	}
	return $actions;
}

function perfectpixel_refund_request_form( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( ! perfectpixel_refund_request_allowed( $order ) ) {
		return;
	}
	echo '<section id="perfectpixel-refund" style="margin-top:2em"><h2>' . esc_html( '{{refund_request_button}}' ) . '</h2><form method="post">';
	wp_nonce_field( 'perfectpixel_refund_' . $order_id, 'perfectpixel_refund_nonce' );
	echo '<input type="hidden" name="perfectpixel_refund_order" value="' . esc_attr( $order_id ) . '">';
	echo '<p><label for="perfectpixel_refund_reason">' . esc_html( '{{refund_request_label}}' ) . '</label><textarea id="perfectpixel_refund_reason" name="perfectpixel_refund_reason" rows="4" required maxlength="1000" style="width:100%"></textarea></p>';
	echo '<p><button type="submit" class="button">' . esc_html( '{{refund_request_button}}' ) . '</button></p></form></section>';
}

function perfectpixel_refund_request_submit() {
	if ( empty( $_POST['perfectpixel_refund_order'] ) || ! is_user_logged_in() ) {
		return;
	}
	$order_id = absint( $_POST['perfectpixel_refund_order'] );
	if ( ! wp_verify_nonce( sanitize_key( $_POST['perfectpixel_refund_nonce'] ?? '' ), 'perfectpixel_refund_' . $order_id ) ) {
		return;
	}
	$order = wc_get_order( $order_id );
	if ( ! $order || (int) $order->get_customer_id() !== get_current_user_id() || ! perfectpixel_refund_request_allowed( $order ) ) {
		return;
	}
	$reason = mb_substr( sanitize_textarea_field( wp_unslash( $_POST['perfectpixel_refund_reason'] ?? '' ) ), 0, 1000 );
	$order->update_meta_data( '_perfectpixel_refund_requested', current_time( 'mysql' ) );
	$order->add_order_note( "Αίτημα επιστροφής από τον πελάτη:\n" . $reason );
	$order->save();
	wp_mail(
		get_option( 'admin_email' ),
		sprintf( 'Αίτημα επιστροφής για την παραγγελία #%s', $order->get_order_number() ),
		sprintf( "Ο πελάτης ζήτησε επιστροφή για την παραγγελία #%s.\n\nΛόγος:\n%s\n\n%s", $order->get_order_number(), $reason, $order->get_edit_order_url() )
	);
	wc_add_notice( '{{refund_request_thanks}}' );
	wp_safe_redirect( $order->get_view_order_url() );
	exit;
}
